update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(91,null::text,$$Colônia Agrícola, Industrial ou Similar$$,$$A Colônia Agrícola, Industrial ou Similar destina-se ao cumprimento da pena em regime semi-aberto.$$),
(92,null,$$Alojamento coletivo$$,$$O condenado pode ser alojado em compartimento coletivo, observados os requisitos da alínea a do parágrafo único do art. 88. São também requisitos básicos das dependências coletivas a seleção adequada dos presos (alínea a) e o limite de capacidade máxima que atenda aos objetivos de individualização da pena (alínea b).$$),
(93,null,$$Casa do Albergado$$,$$A Casa do Albergado destina-se ao cumprimento de pena privativa de liberdade em regime aberto e da pena de limitação de fim de semana.$$),
(94,null,$$Localização da Casa do Albergado$$,$$O prédio deve situar-se em centro urbano, separado dos demais estabelecimentos, e caracterizar-se pela ausência de obstáculos físicos contra a fuga.$$),
(95,null,$$Instalações da Casa do Albergado$$,$$Em cada região haverá pelo menos uma Casa do Albergado, com aposentos para acomodar os presos e local adequado para cursos e palestras. O estabelecimento terá instalações para os serviços de fiscalização e orientação dos condenados (parágrafo único).$$),
(96,null,$$Centro de Observação$$,$$No Centro de Observação realizam-se os exames gerais e o criminológico, cujos resultados são encaminhados à Comissão Técnica de Classificação. No Centro podem ser realizadas pesquisas criminológicas (parágrafo único).$$),
(97,null,$$Instalação do Centro de Observação$$,$$O Centro de Observação é instalado em unidade autônoma ou em anexo a estabelecimento penal.$$),
(98,null,$$Exames pela Comissão Técnica de Classificação$$,$$Na falta do Centro de Observação, os exames podem ser realizados pela Comissão Técnica de Classificação.$$),
(99,null,$$Hospital de Custódia e Tratamento Psiquiátrico$$,$$O Hospital de Custódia e Tratamento Psiquiátrico destina-se aos inimputáveis e semi-imputáveis referidos no artigo 26 e seu parágrafo único do Código Penal. Aplica-se ao hospital, no que couber, o parágrafo único do art. 88 (parágrafo único).$$),
(100,null,$$Exame psiquiátrico dos internados$$,$$O exame psiquiátrico e os demais exames necessários ao tratamento são obrigatórios para todos os internados.$$),
(101,null,$$Tratamento ambulatorial$$,$$O tratamento ambulatorial, previsto na segunda parte do artigo 97 do Código Penal, é realizado no Hospital de Custódia e Tratamento Psiquiátrico ou em outro local com dependência médica adequada.$$),
(102,null,$$Cadeia pública$$,$$A cadeia pública destina-se ao recolhimento de presos provisórios.$$),
(103,null,$$Cadeia pública por comarca$$,$$Cada comarca terá pelo menos uma cadeia pública, a fim de resguardar o interesse da Administração da Justiça Criminal e a permanência do preso em local próximo ao seu meio social e familiar.$$),
(104,null,$$Localização da cadeia pública$$,$$O estabelecimento de que trata o Capítulo é instalado próximo de centro urbano, observando-se na construção as exigências mínimas do artigo 88 e seu parágrafo único.$$),
(105,null,$$Guia de recolhimento$$,$$Transitada em julgado a sentença que aplicar pena privativa de liberdade, se o réu estiver ou vier a ser preso, o juiz ordena a expedição de guia de recolhimento para a execução.$$),
(106,null,$$Conteúdo da guia de recolhimento$$,$$A guia de recolhimento é extraída pelo escrivão, que a rubrica em todas as folhas e a assina com o juiz, e é remetida à autoridade administrativa incumbida da execução. Contém, entre outros itens dos incisos I a VI, o nome e a qualificação do condenado (incisos I e II), o inteiro teor da denúncia e da sentença condenatória e a certidão do trânsito em julgado (inciso III), a data da terminação da pena (inciso V) e outras peças reputadas indispensáveis (inciso VI). Dá-se ciência ao Ministério Público (§ 1º), e a guia é retificada sempre que sobrevier modificação quanto ao início da execução ou ao tempo de duração da pena (§ 2º).$$),
(107,null,$$Recolhimento mediante guia$$,$$Ninguém é recolhido, para cumprimento de pena privativa de liberdade, sem a guia expedida pela autoridade judiciária. A autoridade administrativa passa recibo da guia, para juntá-la aos autos, e dá ciência de seus termos ao condenado (§ 1º), e as guias são registradas em livro especial e anexadas ao prontuário, com aditamento do cálculo das remições e de outras retificações (§ 2º).$$),
(108,null,$$Doença mental superveniente$$,$$O condenado a quem sobrevier doença mental é internado em Hospital de Custódia e Tratamento Psiquiátrico.$$),
(109,null,$$Alvará de soltura$$,$$Cumprida ou extinta a pena, o condenado é posto em liberdade, mediante alvará do juiz, se por outro motivo não estiver preso.$$),
(110,null,$$Regime inicial na sentença$$,$$O juiz, na sentença, estabelece o regime em que o condenado iniciará o cumprimento da pena privativa de liberdade, observado o artigo 33 e seus parágrafos do Código Penal.$$),
(111,null,$$Regime na pluralidade de condenações$$,$$Havendo condenação por mais de um crime, no mesmo processo ou em processos distintos, o regime de cumprimento é determinado pelo resultado da soma ou unificação das penas, observada, quando for o caso, a detração ou remição. Sobrevindo condenação no curso da execução, soma-se a pena ao restante da que está sendo cumprida, para determinação do regime (parágrafo único).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;